node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const order = db.prepare(\"SELECT * FROM orders WHERE order_id = 'ORD-CCC96C'\").all();
console.log('=== ORDER ===');
console.log(JSON.stringify(order, null, 2));

// Also check order_items
const items = db.prepare(\"SELECT * FROM order_items WHERE order_id = 'ORD-CCC96C'\").all();
console.log('=== ORDER ITEMS ===');
console.log(JSON.stringify(items, null, 2));

// Check fulfillments
const fulfillments = db.prepare(\"SELECT * FROM order_fulfillments WHERE order_id = 'ORD-CCC96C'\").all();
console.log('=== FULFILLMENTS ===');
console.log(JSON.stringify(fulfillments, null, 2));

// Check payments
const payments = db.prepare(\"SELECT * FROM order_payments WHERE order_id = 'ORD-CCC96C'\").all();
console.log('=== PAYMENTS ===');
console.log(JSON.stringify(payments, null, 2));

// Check warranties
const warranties = db.prepare(\"SELECT * FROM warranties WHERE order_id = 'ORD-CCC96C'\").all();
console.log('=== WARRANTIES ===');
console.log(JSON.stringify(warranties, null, 2));
"

